import{_ as t,o as n,c as r,a3 as a}from"./chunks/framework.B9qR_F1m.js";const b=JSON.parse('{"title":"Die Karte","description":"","frontmatter":{},"headers":[],"relativePath":"start/karte.md","filePath":"start/karte.md"}'),i={name:"start/karte.md"};function d(s,e,o,u,l,h){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="die-karte" tabindex="-1">Die Karte <a class="header-anchor" href="#die-karte" aria-label="Permalink to &quot;Die Karte&quot;">​</a></h1><p>Die Karte ist das Herz von Shardwing. Sie zeigt die DCS-Karte über einer normalen Weltkarte, darauf Routen, Bedrohungen, Grafiken und alles, was zum gerade offenen Bereich gehört.</p><h2 id="bedienen" tabindex="-1">Bedienen <a class="header-anchor" href="#bedienen" aria-label="Permalink to &quot;Bedienen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Was</th><th>Wie</th></tr></thead><tbody><tr><td>Verschieben</td><td>Ziehen</td></tr><tr><td>Zoomen</td><td>Mausrad, Trackpad oder <strong>+ / −</strong> rechts oben</td></tr><tr><td>Ansicht zurücksetzen</td><td>Fadenkreuz-Knopf rechts oben</td></tr><tr><td>Koordinate kopieren</td><td><strong>Rechtsklick</strong> – unten links steht die Position unter dem Mauszeiger im gewählten Format und als Bullseye-Peilung</td></tr><tr><td>Messen</td><td>Lineal-Knopf oder Taste <kbd>M</kbd>, dann Punkte klicken. Shardwing zeigt Kurs und Distanz je Leg und die Summe. <kbd>Esc</kbd> beendet.</td></tr><tr><td>Bullseye-Peilung</td><td><strong>BE</strong> zieht eine Linie vom Bullseye zum Mauszeiger, mit Peilung und Distanz.</td></tr><tr><td>Bullseye versetzen</td><td>Nur Mission Designer: <strong>BE ⌖</strong>, dann auf die Karte klicken – oder im Bullseye-Popup eine Koordinate eingeben.</td></tr></tbody></table><h2 id="kartenebenen" tabindex="-1">Kartenebenen <a class="header-anchor" href="#kartenebenen" aria-label="Permalink to &quot;Kartenebenen&quot;">​</a></h2><p>Links oben über <strong>DCS-Karte</strong> öffnest du die Ebenen:</p><ul><li><strong>Grundkarte:</strong> eine helle bzw. im Dunkelmodus dunkle Straßenkarte (OpenStreetMap). Sie bleibt außerhalb der DCS-Karte immer sichtbar.</li><li><strong>Anzeige:</strong> Routen der anderen Flights, Wegpunkte auf diesen Routen, Flugplätze, Bodenstationen (VOR, TACAN, NDB).</li><li><strong>Eigene Kräfte:</strong> Flugzeuge, Hubschrauber, Schiffe als NATO-Symbole am Startort. Flights am selben Platz teilen sich ein Symbol; Namen erscheinen ab näherem Zoom.</li></ul><p><strong>Flugplätze und Bodenstationen</strong> gibt es für alle DCS-Karten (Caucasus, Syria, Persian Gulf, Sinai, Iraq, Afghanistan, Kola, Germany CW, Nevada, Normandy, Marianas, Falklands). Ein Klick zeigt Frequenzen, TACAN, ILS und Bahnen.</p><h2 id="symbole-und-farben" tabindex="-1">Symbole und Farben <a class="header-anchor" href="#symbole-und-farben" aria-label="Permalink to &quot;Symbole und Farben&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Auf der Karte</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Blaue Linie mit Nummern</td><td>Route des gewählten Flights, Nummern = Steerpoints</td></tr><tr><td>Rote Raute, Ring</td><td>Freigegebene Bedrohung mit Reichweite</td></tr><tr><td>Graue Raute</td><td>Bedrohung, die (noch) verborgen ist – nur der Designer sieht sie</td></tr><tr><td>Blaue Rahmen-Symbole</td><td>Eigene Luftabwehr und Kräfte (NATO-Symbole)</td></tr><tr><td>Rotes Fadenkreuz</td><td>Bullseye</td></tr><tr><td>Farbige Flächen und Linien</td><td>Zeichnungen aus dem Mission Editor und taktische Grafiken</td></tr></tbody></table><h2 id="routen-direkt-auf-der-karte-bearbeiten" tabindex="-1">Routen direkt auf der Karte bearbeiten <a class="header-anchor" href="#routen-direkt-auf-der-karte-bearbeiten" aria-label="Permalink to &quot;Routen direkt auf der Karte bearbeiten&quot;">​</a></h2><p>Im Bereich <strong>Flights</strong> kannst du die Route des gewählten Flights auf der Karte ändern:</p><ul><li><strong>Punkt ziehen</strong> verschiebt ihn.</li><li><strong>„+“ zwischen zwei Punkten</strong> fügt einen neuen ein.</li><li><strong>Rechtsklick</strong> auf einen Punkt entfernt ihn.</li></ul><p>Hat der Flight eine Cartridge, bearbeitest du deren Steerpoints im <a href="/bereiche/dtc">DTC-Editor</a> – dort setzen Klicks auf die Karte neue Punkte.</p><h2 id="koordinaten-und-zeit" tabindex="-1">Koordinaten und Zeit <a class="header-anchor" href="#koordinaten-und-zeit" aria-label="Permalink to &quot;Koordinaten und Zeit&quot;">​</a></h2><p>Oben rechts wählst du das <strong>Koordinatenformat</strong> (DDM, DMS, DD, MGRS) und den <strong>Zeitbezug</strong> (L = Ortszeit der Karte, Z = Zulu). Das gilt in der ganzen App, auch auf Kneeboards.</p><p>Die Zeitzone jeder Karte ist voreingestellt. Stimmt sie nicht, klick auf <strong>UTC±</strong> und trag die Abweichung ein – sie wird mit der Mission gespeichert.</p>',17)])])}const c=t(i,[["render",d]]);export{b as __pageData,c as default};
